async function importFile(file){if(!file)return;try{
 let data=file.name.toLowerCase().endsWith('.json')?JSON.parse(await file.text()):null;
 if(data){if(data.profile&&data.foodLibrary){state={...deep(seed),...data,version:2};dataStatus='Imported JSON backup '+file.name;}else throw Error('JSON file does not contain a Fit OS backup.');}
 else {if(!file.name.toLowerCase().endsWith('.xlsx'))throw Error('Please select an .xlsx or JSON backup (old binary .xls unsupported).');let sheets=await window.FitXLSX.read(await file.arrayBuffer());let out=importSheets(sheets);if(!out.touched.length)throw Error('No compatible sheets found. Use the connected template or the older IIM Mumbai workbook.');dataStatus=`${file.name}: recognized ${out.touched.join(', ')} (${out.mapped} populated records or reference rows).`;}
 save();activate('dashboard');toast('Excel imported. Dashboard refreshed ✓');
 }catch(e){console.error('Import error',e);dataStatus='Import failed: '+(e?.message||String(e));render();toast(dataStatus)}finally{$('#fileInput').value=''}}
function registerEvents(){document.addEventListener('click',e=>{let t=e.target.closest('[data-nav],[data-open],[data-close-modal],[data-delete],[data-day],[data-recipe],[data-recipe-filter],[data-grocery-filter],[data-edit-grocery],[data-add-recipe],[data-upload],[data-export],[data-reset],[data-install],[data-water-plus],[data-log-food],[data-edit-food-ref],[data-edit-food]');if(!t)return;
 if(t.dataset.nav){activate(t.dataset.nav);return}
 if(t.dataset.open){showEntry(t.dataset.open);return}
 if(t.hasAttribute('data-install')){if(installPrompt){installPrompt.prompt();installPrompt=null;}else modal('Install Fit OS on Android','<p>On Android Chrome, open your published Fit OS website and tap <b>⋮ → Install app</b> (or <b>Add to Home screen</b>). Then launch Fit OS from your home screen.</p><p class="small muted">If the option is missing, verify the site uses HTTPS and refresh it after the GitHub Pages update.</p>');return}
 if(t.dataset.waterPlus){addWater(Number(t.dataset.waterPlus));return}
 if(t.dataset.logFood){showEntry('food');let x=state.foodLibrary[Number(t.dataset.logFood)];$('#fld_food').value=x.food;updateFoodPreview();return}
 if(t.dataset.editFoodRef){showEntry('customFood',Number(t.dataset.editFoodRef));return}
 if(t.dataset.editFood){showEntry('food',Number(t.dataset.editFood));return}
 if(t.hasAttribute('data-close-modal')){closeModal();return}
 if(t.dataset.day){menuDay=t.dataset.day;render();return}
 if(t.dataset.recipe){recipeDetails(t.dataset.recipe);return}
 if(t.dataset.recipeFilter){recipeFilter=t.dataset.recipeFilter;render();return}
 if(t.dataset.groceryFilter){groceryFilter=t.dataset.groceryFilter;render();return}
 if(t.dataset.editGrocery){editGrocery(Number(t.dataset.editGrocery));return}
 if(t.dataset.addRecipe){addRecipe(t.dataset.addRecipe);return}
 if(t.hasAttribute('data-upload')){$('#fileInput').click();return}
 if(t.dataset.export){if(t.dataset.export==='xlsx')exportXLSX();if(t.dataset.export==='json')exportJSON();if(t.dataset.export==='csv')exportCSV();return}
 if(t.dataset.delete){let [key,idx]=t.dataset.delete.split(':');if(confirm('Delete this logged record?')){state[key].splice(Number(idx),1);save();render();toast('Entry deleted')}return}
 if(t.hasAttribute('data-reset')){if(confirm('Clear ALL browser records? This cannot be undone. Export a backup first.')){localStorage.removeItem(KEY);state=deep(seed);activate('dashboard');toast('Local browser data reset')}return}
 });document.addEventListener('submit',e=>{if(e.target.id==='entryForm')saveEntry(e);else if(e.target.id==='groceryEditForm')saveGrocery(e);else if(e.target.id==='profileForm'){e.preventDefault();let vals=Object.fromEntries(new FormData(e.target));for(let [k,v] of Object.entries(vals)){state.profile[k]=typeof state.profile[k]==='number'?Number(v):v;}state.forecast=modelForecast(state.profile.forecast_scenario||'focused');save();render();toast('Targets updated ✓')}});
 document.addEventListener('change',e=>{if(['fld_food','fld_quantity_mode'].includes(e.target.id))updateFoodPreview()});document.addEventListener('input',e=>{if(['fld_quantity','fld_food'].includes(e.target.id))updateFoodPreview();if(e.target.id==='librarySearch'){let pos=e.target.selectionStart;libraryQuery=e.target.value;render();let el=$('#librarySearch');if(el){el.focus();el.setSelectionRange(pos,pos)}}if(e.target.id==='recipeSearch'){let start=e.target.selectionStart;recipeQuery=e.target.value;render();let el=$('#recipeSearch');if(el){el.focus();el.setSelectionRange(start,start)}}else if(e.target.id==='grocerySearch'){let start=e.target.selectionStart;groceryQuery=e.target.value;render();let el=$('#grocerySearch');if(el){el.focus();el.setSelectionRange(start,start)}}});
 $('#dateInput').value=selectedDate;$('#dateInput').addEventListener('change',e=>{selectedDate=e.target.value||localDate(new Date());render()});$('#fileInput').addEventListener('change',e=>importFile(e.target.files?.[0]));$('#topImport').addEventListener('click',()=>activate('sync'));$('#profileBtn').addEventListener('click',()=>activate('settings'));$('#mobileMenu').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#mobileShade').classList.add('show')});$('#mobileClose').addEventListener('click',closeMenu);$('#mobileShade').addEventListener('click',closeMenu);$('#modalLayer').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});document.addEventListener('dragover',e=>{if(e.target.closest('#dropZone')){e.preventDefault();e.target.closest('#dropZone').classList.add('drag')}});document.addEventListener('dragleave',e=>{if(e.target.closest('#dropZone'))e.target.closest('#dropZone').classList.remove('drag')});document.addEventListener('drop',e=>{let z=e.target.closest('#dropZone');if(!z)return;e.preventDefault();z.classList.remove('drag');importFile(e.dataTransfer.files?.[0])});
}


/* Fit OS 2.1 extensions — dynamic recipe nutrition, adjustable forecasts,
   morning weight and manual boAt step-data CSV import. Offline-first, no health API claims. */
const FORECAST_SCENARIOS={
 steady:{label:'Conservative',description:'Focus on consistency, strength and recovery.',points:[[0,25,0],[3,23,0.5],[6,20.5,1.2],[9,18.5,2.0],[12,16.5,2.6]]},
 focused:{label:'Focused fat loss',description:'Noticeable definition with muscle retention prioritized; still an estimate.',points:[[0,25,0],[3,21.8,0.7],[6,18.2,1.5],[9,15.4,2.2],[12,12.8,3.0]]},
 stretch:{label:'Stretch goal — not a requirement',description:'17% at 6 months and 10% at 12 months requires exceptional adherence and health/recovery checks. Do not force it.',points:[[0,25,0],[3,21.5,0.8],[6,17,1.5],[9,13.8,2.3],[12,10,3.0]]}
};
function modelForecast(scenario){
 const d=FORECAST_SCENARIOS[scenario]||FORECAST_SCENARIOS.focused,p=state.profile,startW=Number(p.start_weight_kg)||75,startBF=Number(p.body_fat_pct)||25;
 const lean0=startW*(1-startBF/100),fat0=startW-lean0;
 return Array.from({length:13},(_,month)=>{
  let a=d.points[0],b=d.points[d.points.length-1];for(let i=1;i<d.points.length;i++){if(month<=d.points[i][0]){a=d.points[i-1];b=d.points[i];break}}
  let frac=(month-a[0])/(b[0]-a[0]||1),bfTarget=startBF+(b[1]-25+(a[1]-25)+(b[1]-a[1])*(frac-1)) ;
  // Interpolate deviations from the reference starting BF (25%).
  bfTarget=startBF + (a[1]-25)+(b[1]-a[1])*frac;
  const leanGain=a[2]+(b[2]-a[2])*frac;
  const weight=(lean0+leanGain)/(1-bfTarget/100),fat=weight-(lean0+leanGain);
  return {month,fat_lost_kg:+(fat0-fat).toFixed(2),muscle_gained_kg:+leanGain.toFixed(2),weight_kg:+weight.toFixed(2),body_fat_pct:+bfTarget.toFixed(1),scenario:d.label+' · mathematical projection, not predicted muscle gain'};
 });
}
function chooseForecast(s){if(!FORECAST_SCENARIOS[s])return;state.profile.forecast_scenario=s;state.forecast=modelForecast(s);save();render();toast('Projection scenario updated — not a guaranteed outcome')}
function calcRecipe(r){
 const parts=(r.ingredientsList||[]).filter(x=>foodRef(x.food)&&Number(x.quantity)>0),yieldN=Math.max(1,Number(r.servingsYield)||1),totals={},coverage={};
 for(const k of NUTRIENT_KEYS){let sum=0,known=0;for(const ing of parts){let f=foodRef(ing.food);if(isKnown(f[k])){sum+=Number(f[k])*Number(ing.quantity)/(Number(f.portion)||1);known++}}
  totals[k]=parts.length&&known===parts.length?+(sum/yieldN).toFixed(4):null;coverage[k]=`${known}/${parts.length}`;
 }
 return {nutrients:totals,coverage,parts,perServingTotalG:isKnown(r.cookedYieldG)&&Number(r.cookedYieldG)>0?Number(r.cookedYieldG)/yieldN:null};
}
function refreshRecipeReferences(){
 for(const rec of state.recipes){if(!Array.isArray(rec.ingredientsList)||!rec.ingredientsList.length)continue;const x=calcRecipe(rec);
  for(const key of NUTRIENT_KEYS)rec[key]=x.nutrients[key];
  const name='Recipe: '+rec.name;let f=foodRef(name),base={food:name,portion:1,unit:'serving',...x.nutrients,source:'Computed from weighed ingredients in Fit OS; omissions remain unknown',notes:'Batch yield: '+rec.servingsYield+' servings. Check raw/cooked weights, optional seasonings and oil.'};
  if(f)Object.assign(f,base);else state.foodLibrary.push(base);
 }
 for(let log of state.foodLogs){if(String(log.food||'').startsWith('Recipe: ')&&foodRef(log.food)&&Number(log.servings)>0){Object.assign(log,foodMacros(log.food,Number(log.servings)))}}
}
// Render replacement: brand-new dynamic recipe cards and a measured ingredient builder.
function renderRecipes(){let categories=['All',...new Set(state.recipes.map(x=>x.category||'Other'))],list=state.recipes.filter(x=>(recipeFilter==='All'||x.category===recipeFilter)&&(`${x.name} ${x.ingredients}`).toLowerCase().includes(recipeQuery.toLowerCase()));return `${header('Recipe library & meal builder','Choose from preloaded recipes or create your own. Every measured ingredient contributes to the nutrition calculation.',`<input id="recipeSearch" class="search" placeholder="Search 24 recipes…" value="${esc(recipeQuery)}"/><button class="btn btn-primary" data-new-recipe>＋ Create recipe</button>`)}<div class="filters" style="margin-bottom:17px">${categories.map(c=>`<button class="filter-pill ${recipeFilter===c?'active':''}" data-recipe-filter="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="card-list">${list.map(x=>`<div class="panel recipe-card"><img class="image-recipe" src="${imageFor(x)}" alt="Illustration for ${esc(x.name)}"/><div class="recipe-card-content"><span class="tag">${esc(x.category)}</span><h3>${esc(x.name)}</h3><p class="small muted">${esc(x.ingredients)}</p><div class="split small"><b class="mint">${num(x.protein,1)} g protein</b><span>${esc(x.minutes)} min · ${num(x.calories,0)} kcal</span></div><div class="recipe-buttons"><button class="btn btn-ghost" data-recipe="${esc(x.id)}">View recipe</button><button class="btn btn-primary" data-recipe-portion="${esc(x.id)}">＋ Log portion</button></div></div></div>`).join('')}</div><div class="support-note" style="margin-top:16px">Ingredient and nutrition data are general estimates or label-based references. A missing micronutrient is <b>Unknown</b>; a recipe with incomplete ingredient data may show an unknown total. For a rice bowl, weigh chicken <b>raw</b> if the database uses raw chicken, and rice <b>cooked</b> if the database uses cooked rice.</div>`}
function recipeDetails(id){let r=state.recipes.find(x=>x.id===id);if(!r)return;let x=calcRecipe(r);modal(r.name,`<div class="recipe-detail"><img src="${imageFor(r)}" alt="${esc(r.name)} illustration"/><div class="filters" style="margin:12px 0">${tag(r.category||'Recipe')}${tag((r.minutes||'')+' min','blue-tag')}${tag('Yield '+(r.servingsYield||1)+' portions','orange-tag')}</div><div class="three-cols"><div class="info-block"><strong>${num(r.calories,0)}</strong><small>kcal / portion</small></div><div class="info-block"><strong>${num(r.protein,1)} g</strong><small>Protein / portion</small></div><div class="info-block"><strong>${num(r.carbs,1)} g</strong><small>Carbs / portion</small></div></div><h3>Weighed ingredients (full batch)</h3>${table(['Food','Amount','Reference'],(r.ingredientsList||[]).map(i=>{let f=foodRef(i.food);return `<tr><td>${esc(i.food)}</td><td>${num(i.quantity,1)} ${esc(f?.unit||'')}</td><td>${f?'Label / estimated':'Missing source'}</td></tr>`}).join(''))}<p class="small muted">${esc(r.ingredients||'')}</p><h3>Step-by-step cooking</h3><ol>${String(r.steps||'').split('|').filter(Boolean).map(s=>`<li>${esc(s.replace(/^\s*\d+\.\s*/,''))}</li>`).join('')}</ol><div class="safety"><b>Storage and food safety:</b> ${esc(r.safety||'Eat perishable foods promptly; no refrigerator available.')}</div><p class="small muted">Equipment: ${esc(r.equipment||'Basic hostel utensils')} · Estimated nutrition. Recipe yield in grams must be measured after cooking.</p><div class="recipe-buttons"><button class="btn btn-primary" data-recipe-portion="${esc(r.id)}">＋ Log amount eaten</button><button class="btn btn-ghost" data-edit-recipe="${esc(r.id)}">Edit ingredients</button></div></div>`)}
function recipeRow(i={food:'',quantity:''},index=0){return `<div class="ingredient-entry"><div class="field"><label>Ingredient ${index+1}</label><input type="search" list="recipeFoods" class="ingredient-food" value="${esc(i.food)}" placeholder="Search saved food…"/></div><div class="field"><label>Quantity (food reference unit)</label><input type="number" class="ingredient-qty" min="0" step="any" value="${esc(i.quantity)}" placeholder="e.g., 250"/></div><button type="button" class="btn btn-small btn-danger" data-remove-ingredient title="Remove ingredient">✕</button></div>`}
function showRecipeBuilder(id=null){let r=state.recipes.find(x=>x.id===id)||null,parts=r?.ingredientsList?.length?r.ingredientsList:[{food:'',quantity:''}];const foodOpts=state.foodLibrary.filter(x=>!x.food.startsWith('Recipe: ')).map(x=>`<option value="${esc(x.food)}"></option>`).join('');modal(r?'Edit measured recipe':'Create your own recipe',`<form id="recipeBuilderForm" data-edit-id="${esc(id||'')}"><p class="small muted">Add each ingredient and its weighed quantity. The app reads the existing food's per-reference nutrients and scales them. Use separate raw/cooked references.</p><div class="form-grid"><div class="field"><label>Recipe name</label><input name="recipe_name" required value="${esc(r?.name||'')}" placeholder="Example: Chicken rice bowl"/></div><div class="field"><label>Category</label><select name="category">${['Protein bowl','Salad','Breakfast','Chicken','Fish','Soy','Snack','Mess','Custom'].map(c=>`<option ${r?.category===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label>Cooking time (min)</label><input type="number" name="minutes" min="0" value="${esc(r?.minutes||15)}"/></div><div class="field"><label>Servings prepared in this batch</label><input type="number" min="1" step="any" name="servingsYield" value="${esc(r?.servingsYield||1)}"/></div><div class="field"><label>Final cooked batch weight (g, optional)</label><input type="number" min="0" step="any" name="cookedYieldG" value="${esc(r?.cookedYieldG||'')}" placeholder="Weigh after cooking"/></div><div class="field"><label>Illustration</label><select name="image">${['chicken','soy','salad','oats','eggs','fish'].map(c=>`<option ${r?.image===c?'selected':''}>${c}</option>`).join('')}</select></div></div><h3>Recipe ingredients</h3><datalist id="recipeFoods">${foodOpts}</datalist><div id="ingredientRows">${parts.map(recipeRow).join('')}</div><div class="recipe-buttons" style="margin:12px 0"><button type="button" class="btn btn-ghost" data-add-ingredient>＋ Add ingredient</button><button type="button" class="btn btn-ghost" data-nav="foodlibrary">Food missing? Add it to database</button></div><div id="recipeLive" class="support-note">Add ingredients to calculate.</div><div class="field"><label>Cooking steps (separate steps with |)</label><textarea name="steps" rows="3" required>${esc(r?.steps||'1. Prepare all ingredients|2. Cook safely|3. Serve immediately')}</textarea></div><div class="field"><label>Food safety / storage</label><textarea name="safety" rows="2">${esc(r?.safety||'No refrigerator: cook and eat fresh. Refrigerate perishables only if safely available.')}</textarea></div><div class="field"><label>Equipment</label><input name="equipment" value="${esc(r?.equipment||'Pan or induction and utensils')}"/></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Cancel</button><button type="submit" class="btn btn-primary">Save calculated recipe</button></div></form>`);updateRecipePreview()}
function formIngredients(){return [...document.querySelectorAll('#ingredientRows .ingredient-entry')].map(x=>({food:x.querySelector('.ingredient-food').value.trim(),quantity:Number(x.querySelector('.ingredient-qty').value)})).filter(x=>x.food||x.quantity)}
function updateRecipePreview(){let f=$('#recipeBuilderForm'),p=$('#recipeLive');if(!f||!p)return;let parts=formIngredients(),bad=parts.filter(x=>!foodRef(x.food)||!(x.quantity>0));let temp={ingredientsList:parts,servingsYield:Number(f.elements.servingsYield.value)||1,cookedYieldG:f.elements.cookedYieldG.value};let x=calcRecipe(temp);p.innerHTML=`<b>Live per-portion nutrition</b><p class="small">${parts.length} ingredients · ${bad.length?bad.length+' ingredient(s) need a saved food/positive amount':'All ingredients matched'} · ${num(temp.servingsYield)} portions</p><div class="preview-stats">${['calories','protein','carbs','fat','fibre','calcium','iron','b12','vitamin_c','omega3','cost'].map(k=>{let nutrient=NUTRIENTS.find(n=>n[0]===k);return `<span>${esc(nutrient?.[1]||k)}: <strong>${isKnown(x.nutrients[k])?num(x.nutrients[k],1)+' '+esc(nutrient[2]):'Unknown'}</strong></span>`}).join('')}</div><p class="tiny-note">If any ingredient lacks a nutrient, that total remains Unknown rather than treating missing values as zero.</p>`}
function saveRecipeBuilder(e){e.preventDefault();let f=e.target,parts=formIngredients(),invalid=parts.filter(x=>!foodRef(x.food)||!(x.quantity>0));if(!parts.length||invalid.length){toast('Select saved foods and enter positive quantities for every ingredient.');return}let vals=Object.fromEntries(new FormData(f)),id=f.dataset.editId;let old=state.recipes.find(x=>x.id===id),name=vals.recipe_name.trim();if(!name){toast('Enter a recipe name');return}let r={...(old||{}),id:old?.id||'USR-'+Date.now().toString(36),name,category:vals.category,minutes:Number(vals.minutes)||15,servingsYield:Number(vals.servingsYield)||1,cookedYieldG:vals.cookedYieldG?Number(vals.cookedYieldG):'',image:vals.image||'salad',steps:vals.steps||'',equipment:vals.equipment||'',safety:vals.safety||'',ingredientsList:parts,ingredients:parts.map(p=>`${num(p.quantity,1)} ${foodRef(p.food)?.unit||''} ${p.food}`).join('; ')};if(old){let former='Recipe: '+old.name;if(old.name!==name){state.foodLibrary=state.foodLibrary.filter(x=>x.food!==former);for(let log of state.foodLogs)if(log.food===former)log.food='Recipe: '+name}Object.assign(old,r)}else state.recipes.push(r);refreshRecipeReferences();save();closeModal();render();toast('Recipe nutrients saved and recalculated ✓')}
function showRecipePortion(id){let r=state.recipes.find(x=>x.id===id);if(!r)return;let x=calcRecipe(r);modal('Log '+r.name,`<form id="recipePortionForm" data-recipe="${esc(id)}"><p class="small muted">Choose servings or enter the exact weight of a finished portion if you've recorded the cooked batch weight.</p><div class="form-grid">${inputField(['date','Date','date',selectedDate])}${inputField(['meal','Meal','select','Lunch',['Breakfast','Lunch','Dinner','Snack','Pre-workout','Post-workout']])}<div class="field"><label>Portion unit</label><select name="mode" id="recipeQtyMode"><option value="servings">Number of servings</option>${x.perServingTotalG?'<option value="grams">Weight eaten in grams</option>':''}</select></div><div class="field"><label>Amount eaten</label><input name="amount" type="number" step="any" min="0.01" id="recipeQty" value="1" required/></div></div><div class="support-note" id="recipePortionPreview"></div><div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Cancel</button><button type="submit" class="btn btn-primary">Log recipe to diary</button></div></form>`);updateRecipePortionPreview()}
function calcRecipeServings(f){let r=state.recipes.find(x=>x.id===f.dataset.recipe);if(!r)return 0;let amount=Number(f.elements.amount.value),mode=f.elements.mode.value;return mode==='grams'?amount/(Number(r.cookedYieldG)/(Number(r.servingsYield)||1)):amount}
function updateRecipePortionPreview(){let f=$('#recipePortionForm'),p=$('#recipePortionPreview');if(!f||!p)return;let r=state.recipes.find(x=>x.id===f.dataset.recipe),count=calcRecipeServings(f),n=foodMacros('Recipe: '+r.name,count);p.innerHTML=`<b>Live amount: ${num(count,2)} servings</b><div class="preview-stats">${['calories','protein','carbs','fat','fibre','calcium','iron','vitamin_c'].map(k=>`<span>${esc(NUTRIENTS.find(x=>x[0]===k)?.[1]||k)} <strong>${isKnown(n[k])?num(n[k],1):'Unknown'}</strong></span>`).join('')}</div>`}
function saveRecipePortion(e){e.preventDefault();let f=e.target,r=state.recipes.find(x=>x.id===f.dataset.recipe),count=calcRecipeServings(f);if(!r||!(count>0)){toast('Enter a positive portion or weight');return}let amount=Number(f.elements.amount.value),mode=f.elements.mode.value,name='Recipe: '+r.name;state.foodLogs.push({date:f.elements.date.value,meal:f.elements.meal.value,food:name,quantity:amount,quantity_mode:mode==='grams'?'grams':'servings',servings:count,portion_consumed:amount,portion_unit:mode==='grams'?'g':'servings',...foodMacros(name,count),notes:'Based on recipe ingredient weights. Batch servings='+r.servingsYield});save();closeModal();render();toast('Recipe portion added to your nutrition diary ✓')}
function renderWearables(){let arr=groupDate(state.dailyHabits).filter(x=>isKnown(x.steps)),today=state.dailyHabits.find(x=>x.date===selectedDate);return `${header('Watch, steps & morning weight','Sync boAt Crest with your phone where supported; enter steps manually here or import an exported CSV. Automatic Crest access is NOT included.',`<button class="btn btn-primary" data-morning-weight>🌅 Morning weigh-in</button><button class="btn btn-ghost" data-open="habits">Edit steps / sleep</button>`)}<div class="section-grid">${pnl(`<div class="three-cols"><div class="info-block"><strong>${isKnown(today?.steps)?Number(today.steps).toLocaleString('en-IN'):'—'}</strong><small>Steps recorded today</small></div><div class="info-block"><strong>${isKnown(today?.sleep_h)?num(today.sleep_h,1):'—'}</strong><small>Sleep last night (h)</small></div><div class="info-block"><strong>${state.measurements.filter(x=>x.date===selectedDate).length?'✓':'—'}</strong><small>Morning weight today</small></div></div><div class="recipe-buttons" style="margin-top:14px"><button class="btn btn-primary" data-add-steps>＋ Enter daily steps</button><button class="btn btn-ghost" data-import-steps>⬆ Import steps CSV</button><button class="btn btn-ghost" data-export-steps-template>↓ CSV template</button></div><div class="support-note" style="margin-top:12px">Official boAt Lunar Discovery documentation reports Google Fit step-sharing, but not automatic Fit OS access. Google Fit legacy APIs are being retired. Direct automatic steps from Android Health Connect need a <b>native Android integration</b> and your explicit permission. This GitHub Pages PWA cannot read your watch silently.</div>`,'col12')}${pnl(`${panelTitle('↗','Recorded steps trend')}${arr.length?lineChart([{name:'Daily steps',color:'#9deb75',values:arr.slice(0,14).reverse().map(x=>x.steps),labels:arr.slice(0,14).reverse().map(x=>x.date.slice(5))}],190):empty('No steps logged yet','Enter watch steps or import a compatible CSV.')}`,'col6')}${pnl(`${panelTitle('⌁','Recent synced or manual entries')}${table(['Date','Steps','Sleep'],arr.slice(0,14).map(x=>`<tr><td>${esc(x.date)}</td><td>${isKnown(x.steps)?Number(x.steps).toLocaleString('en-IN'):'—'}</td><td>${isKnown(x.sleep_h)?num(x.sleep_h,1)+' h':'—'}</td></tr>`).join(''))}`,'col6')}</div>`}
function morningWeight(){let prior=groupDate(state.measurements).find(x=>isKnown(x.weight_kg)),today=state.measurements.find(x=>x.date===selectedDate);modal('Morning weight check-in',`<form id="morningWeightForm"><p class="small muted">After using the toilet, before breakfast, under similar conditions. Use weekly averages, not individual daily fluctuations.</p>${inputField(['date','Date','date',selectedDate])}${inputField(['weight_kg','Weight (kg)','number',today?.weight_kg??prior?.weight_kg??''])}${inputField(['waist_cm','Waist (cm, optional)','number',today?.waist_cm??''])}${inputField(['notes','Notes (optional)','textarea',today?.notes??''])}<div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Cancel</button><button type="submit" class="btn btn-primary">Save morning weigh-in</button></div></form>`)}
function saveMorningWeight(e){e.preventDefault();let f=e.target,v=Number(f.elements.weight_kg.value),date=f.elements.date.value;if(!Number.isFinite(v)||v<30||v>250){toast('Enter a valid weight in kilograms');return}let old=state.measurements.find(x=>x.date===date);if(!old){old={date};state.measurements.push(old)}old.weight_kg=v;if(f.elements.waist_cm.value)old.waist_cm=Number(f.elements.waist_cm.value);old.notes=f.elements.notes.value||old.notes||'';old.checkin_time='morning';save();closeModal();render();toast('Morning weight saved ✓')}
function addSteps(){let existing=state.dailyHabits.find(x=>x.date===selectedDate);modal('Enter daily steps',`<form id="stepsForm">${inputField(['date','Date','date',selectedDate])}${inputField(['steps','Steps from boAt / phone','number',isKnown(existing?.steps)?existing.steps:''])}<div class="modal-actions"><button type="button" class="btn btn-ghost" data-close-modal>Cancel</button><button type="submit" class="btn btn-primary">Save steps</button></div></form>`)}
function saveSteps(e){e.preventDefault();let f=e.target,date=f.elements.date.value,steps=Number(f.elements.steps.value);if(!Number.isInteger(steps)||steps<0||steps>100000){toast('Enter a valid number of steps');return}let old=state.dailyHabits.find(x=>x.date===date);if(!old){old={date};state.dailyHabits.push(old)}old.steps=steps;old.step_source='Manual watch/phone entry';save();closeModal();render();toast('Steps recorded ✓')}
function csvSplit(line){let a=[],v='',quote=false;for(let i=0;i<line.length;i++){let c=line[i];if(c==='"'){if(quote&&line[i+1]==='"'){v+='"';i++}else quote=!quote}else if(c===','&&!quote){a.push(v.trim());v=''}else v+=c}a.push(v.trim());return a}
async function importStepsCsv(file){if(!file)return;try{let txt=await file.text(),rows=txt.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean).map(csvSplit);if(rows.length<2)throw Error('CSV needs a heading row and at least one record.');let heads=rows.shift().map(x=>x.toLowerCase().replace(/[^a-z0-9]/g,'')),idx=(...keys)=>heads.findIndex(x=>keys.includes(x)),dI=idx('date','day','datetime','startdate'),sI=idx('steps','stepcount','totalsteps'),hI=idx('sleep','sleephours','sleeph','sleepdurationhours');if(dI<0||sI<0)throw Error('CSV must contain Date and Steps columns. Download the sample template.');let count=0;for(const a of rows){let day=parseDay(a[dI]||''),steps=Number(a[sI]);if(!/^\d{4}-\d\d-\d\d$/.test(day)||!Number.isInteger(steps)||steps<0||steps>100000)continue;let old=state.dailyHabits.find(x=>x.date===day);if(!old){old={date:day};state.dailyHabits.push(old)}old.steps=steps;old.step_source='Imported from '+file.name;if(hI>=0&&a[hI]!==''&&a[hI]!==undefined&&Number.isFinite(Number(a[hI])))old.sleep_h=Number(a[hI]);count++}if(!count)throw Error('No valid dated steps found. Use YYYY-MM-DD dates.');save();render();toast(count+' watch step day(s) imported ✓')}catch(err){toast('CSV import failed: '+err.message)}}
function exportStepsTemplate(){download(new Blob(['Date,Steps,Sleep Hours\n2026-11-05,8500,7.5\n'],{type:'text/csv'}),'Fit_OS_Steps_Template.csv')}
function foodCatalogCsv(){let keys=['Food','Portion','Unit',...NUTRIENT_KEYS,'Source','Notes'];let rows=[keys,...state.foodLibrary.map(x=>[x.food,x.portion,x.unit,...NUTRIENT_KEYS.map(k=>isKnown(x[k])?x[k]:''),x.source||'',x.notes||''])];return rows.map(x=>x.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}
function exportFoodCatalog(){download(new Blob(['\ufeff'+foodCatalogCsv()],{type:'text/csv;charset=utf-8'}),'Fit_OS_Food_Catalog.csv')}
async function importFoodCsv(file){if(!file)return;try{let txt=await file.text(),rows=txt.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean).map(csvSplit);if(rows.length<2)throw Error('A CSV heading and food rows are required');let h=rows.shift().map(x=>x.toLowerCase().replace(/[^a-z0-9]/g,''));const i=(...keys)=>h.findIndex(x=>keys.includes(x));let nameI=i('food','name','product','foodname'),portionI=i('portion','referencequantity','servingsize'),unitI=i('unit','servingunit');if(nameI<0||portionI<0||unitI<0)throw Error('CSV requires Food, Portion and Unit columns');let count=0;for(let row of rows){let name=String(row[nameI]||'').trim(),portion=Number(row[portionI]);if(!name||!(portion>0))continue;let ent={food:name,portion,unit:row[unitI]||'g',source:'Imported from '+file.name};for(let k of NUTRIENT_KEYS){let ix=i(k.replace(/[^a-z0-9]/g,''));ent[k]=ix>=0&&row[ix]!==''&&Number.isFinite(Number(row[ix]))?Number(row[ix]):null}let prev=foodRef(name);if(prev)Object.assign(prev,ent);else state.foodLibrary.push(ent);count++}if(!count)throw Error('No valid foods found');refreshRecipeReferences();save();render();toast(count+' nutrition products imported and recipes recalculated ✓')}catch(err){toast('Food CSV: '+err.message)}}
function renderGoals(){let f=state.forecast,m=groupDate(state.measurements),scenario=state.profile.forecast_scenario||'focused',d=FORECAST_SCENARIOS[scenario];return`${header('Recomposition goals · realistic vs stretch','Track your actual waist, average morning weight, strength, sleep and recovery. The curves are target scenarios, not predictions.',`<button class="btn btn-primary" data-morning-weight>🌅 Morning check-in</button><button class="btn btn-ghost" data-open="review">＋ Weekly review</button>`)}<div class="quote-banner"><h3>Build muscle. Get leaner. Keep your performance.</h3><p>Your strength and recovery matter more than chasing a single body-fat number.</p></div><div class="filters" style="margin:18px 0">${Object.entries(FORECAST_SCENARIOS).map(([k,x])=>`<button class="filter-pill ${scenario===k?'active':''}" data-forecast-mode="${k}">${esc(x.label)}</button>`).join('')}</div><div class="support-note"><b>${esc(d.label)}:</b> ${esc(d.description)} A 25% visual body-fat estimate may be inaccurate; improving measurement precision changes every target weight. “Modeled gain” below represents <b>fat-free mass</b> and isn't measured muscle tissue.</div><div class="section-grid">${pnl(`<div class="three-cols">${[3,6,9,12].map(month=>`<div class="info-block"><span class="muted micro">${month} MONTH ESTIMATE</span><strong>${num(f[month].body_fat_pct,1)}%</strong><small>Model weight ${num(f[month].weight_kg,1)} kg · fat loss ${num(f[month].fat_lost_kg,1)} kg · modeled lean gain ${num(f[month].muscle_gained_kg,1)} kg</small></div>`).join('')}</div>`,'col12')}${pnl(`${panelTitle('↗','Body-fat target scenario')}${lineChart([{name:'Target model',color:'#f38cc9',values:f.map(x=>x.body_fat_pct),labels:f.map(x=>x.month===0?'Now':x.month+'m')}],230)}`,'col6')}${pnl(`${panelTitle('↗','Scale-weight target scenario')}${lineChart([{name:'Weight model',color:'#9deb75',values:f.map(x=>x.weight_kg),labels:f.map(x=>x.month===0?'Now':x.month+'m')}],230)}`,'col6')}${pnl(`${panelTitle('🌅','What you can actually control')}<p class="small muted">Weigh after waking and using the bathroom before breakfast. Compare 7-day averages and waist circumference. Use strength progression and photos monthly. Aim for a modest, sustainable energy deficit; adjust calories after 2–3 weeks of real trends, not from modelled dates. Facial fat cannot be spot-reduced. If football performance, mood or recovery deteriorate, ease the deficit.</p><button class="btn btn-primary" data-morning-weight>Log morning weight</button>`,'col12')}${pnl(`${panelTitle('▤','All 12 monthly planning values')}${table(['Month','Estimated fat loss','Modeled lean gain','Weight','Body fat'],f.map(x=>`<tr><td>${x.month||'Start'}</td><td>${num(x.fat_lost_kg,2)} kg</td><td>${num(x.muscle_gained_kg,2)} kg</td><td>${num(x.weight_kg,2)} kg</td><td>${num(x.body_fat_pct,1)}%</td></tr>`).join(''))}`,'col12')}</div>`}

if(!Array.isArray(state.microsDaily))state.microsDaily=[];
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});

if(!Array.isArray(state.recipes))state.recipes=[];
for(const s of seed.recipes){let old=state.recipes.find(x=>x.id===s.id);if(!old)state.recipes.push(deep(s));else if(!Array.isArray(old.ingredientsList)||!old.ingredientsList.length){old.ingredientsList=deep(s.ingredientsList);old.servingsYield=s.servingsYield;old.cookedYieldG=s.cookedYieldG}}
if(!state.profile.forecast_scenario||!FORECAST_SCENARIOS[state.profile.forecast_scenario])state.profile.forecast_scenario='focused';
state.forecast=modelForecast(state.profile.forecast_scenario);
refreshRecipeReferences();

registerEvents();

document.addEventListener('click',e=>{
 let t=e.target.closest('[data-new-recipe],[data-edit-recipe],[data-recipe-portion],[data-add-ingredient],[data-remove-ingredient],[data-forecast-mode],[data-morning-weight],[data-add-steps],[data-import-steps],[data-export-steps-template],[data-food-csv-import],[data-food-csv-export]');if(!t)return;
 if(t.hasAttribute('data-new-recipe')){showRecipeBuilder();return}
 if(t.hasAttribute('data-edit-recipe')){showRecipeBuilder(t.dataset.editRecipe);return}
 if(t.hasAttribute('data-recipe-portion')){showRecipePortion(t.dataset.recipePortion);return}
 if(t.hasAttribute('data-add-ingredient')){let el=$('#ingredientRows');el.insertAdjacentHTML('beforeend',recipeRow({food:'',quantity:''},el.children.length));updateRecipePreview();return}
 if(t.hasAttribute('data-remove-ingredient')){let el=t.closest('.ingredient-entry');if($('#ingredientRows').children.length>1)el.remove();else {el.querySelector('.ingredient-food').value='';el.querySelector('.ingredient-qty').value=''};updateRecipePreview();return}
 if(t.hasAttribute('data-forecast-mode')){chooseForecast(t.dataset.forecastMode);return}
 if(t.hasAttribute('data-morning-weight')){morningWeight();return}
 if(t.hasAttribute('data-add-steps')){addSteps();return}
 if(t.hasAttribute('data-import-steps')){$('#stepsCsvInput').click();return}
 if(t.hasAttribute('data-export-steps-template')){exportStepsTemplate();return}
 if(t.hasAttribute('data-food-csv-import')){$('#foodsCsvInput').click();return}
 if(t.hasAttribute('data-food-csv-export')){exportFoodCatalog();return}
});
