window.FitOSBridge={getState:()=>deep(state),applyState:(incoming)=>{
 if(!incoming||!incoming.profile||!Array.isArray(incoming.foodLogs))throw Error('Invalid Fit OS cloud data');
 state={...deep(seed),...deep(incoming)};
 for(const ref of seed.foodLibrary)if(!state.foodLibrary.some(x=>x.food.toLowerCase()===ref.food.toLowerCase()))state.foodLibrary.push(deep(ref));
 if(!Array.isArray(state.recipes))state.recipes=[];
 for(const r of seed.recipes){const old=state.recipes.find(x=>x.id===r.id);if(!old)state.recipes.push(deep(r));else if(!Array.isArray(old.ingredientsList)||!old.ingredientsList.length){old.ingredientsList=deep(r.ingredientsList);old.servingsYield=r.servingsYield;old.cookedYieldG=r.cookedYieldG}}
 if(!state.profile.forecast_scenario||!FORECAST_SCENARIOS[state.profile.forecast_scenario])state.profile.forecast_scenario='focused';
 state.forecast=modelForecast(state.profile.forecast_scenario);refreshRecipeReferences();save();navRender();render();
}};
